#define NEW new

class slc_anim_t
{
public:
  slc_anim_t(const char*, int);
};

class slf_anim_pause_t
{
public:
  slf_anim_pause_t(slc_anim_t*, const char*);
};

class slf_anim_set_timescale_t
{
public:
  slf_anim_set_timescale_t(slc_anim_t*, const char*);
};

class slf_anim_set_time_t
{
public:
  slf_anim_set_time_t(slc_anim_t*, const char*);
};

class slf_anim_play_t
{
public:
  slf_anim_play_t(slc_anim_t*, const char*);
};

class slf_anim_wait_finished_t
{
public:
  slf_anim_wait_finished_t(slc_anim_t*, const char*);
};

class slf_anim_kill_anim_t
{
public:
  slf_anim_kill_anim_t(slc_anim_t*, const char*);
};

class slf_load_anim_t
{
public:
  slf_load_anim_t(const char*);
};

void register_anim_lib()
{
  slc_anim_t* slc_anim = NEW slc_anim_t("anim",4);

  NEW slf_anim_pause_t(slc_anim,"pause()");
  NEW slf_anim_set_timescale_t(slc_anim,"set_timescale(num)");
  NEW slf_anim_set_time_t(slc_anim,"set_time(num)");
  NEW slf_anim_play_t(slc_anim,"play()");
  NEW slf_anim_wait_finished_t(slc_anim,"wait_finished()");
  NEW slf_anim_kill_anim_t(slc_anim,"kill_anim()");
  NEW slf_load_anim_t("load_anim(str)");
}
